SELECT CASE WHEN cost >= 82 THEN 'high' WHEN cost >= 32 THEN 'mid' ELSE 'low' END AS cost_bucket, CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END AS shipped_cohort, SUM(CASE WHEN status = 'LOST' THEN cost ELSE 0 END) AS lost_cost FROM shipments WHERE delivered_date > '2024-02-22' GROUP BY CASE WHEN cost >= 82 THEN 'high' WHEN cost >= 32 THEN 'mid' ELSE 'low' END, CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END HAVING SUM(CASE WHEN status = 'LOST' THEN cost ELSE 0 END) >= 45 ORDER BY shipped_cohort ASC;
